#!/usr/bin/env python3
"""Gold Price Dynamics Report Generator — produces /app/output/final_report.html"""

import pandas as pd
import numpy as np
from scipy import stats
import plotly.graph_objects as go
import plotly.subplots as sp
from plotly.utils import PlotlyJSONEncoder
import json
from datetime import datetime, timedelta

# ── 1. LOAD & PARSE ──────────────────────────────────────────────────────────

df = pd.read_csv("/app/benchmark/data.csv")
df["Date"] = pd.to_datetime(df["Date"], format="%d-%m-%y")

# Fix two-digit year cutoff: pandas interprets "26" as 2026 correctly via %y,
# but "00"–"68" become 2000–2068 and "69"–"99" become 1969–1999.
# Our data is all 2000+ so we're fine, but let's ensure no pre-2000 dates exist.
mask_old = df["Date"].dt.year < 2000
df.loc[mask_old, "Date"] = df.loc[mask_old, "Date"] + pd.DateOffset(years=100)

df = df.sort_values("Date").reset_index(drop=True)

# Compute log returns
df["LogReturn"] = np.log(df["Close"] / df["Close"].shift(1))
df["Return"] = df["Close"].pct_change()

# ── 2. KPIs ──────────────────────────────────────────────────────────────────

start_price = df["Close"].iloc[0]
end_price = df["Close"].iloc[-1]
n_days = len(df)
n_years = (df["Date"].iloc[-1] - df["Date"].iloc[0]).days / 365.25

cagr = (end_price / start_price) ** (1 / n_years) - 1
ann_vol = df["LogReturn"].std() * np.sqrt(252)
rolling_max = df["Close"].cummax()
drawdown = (df["Close"] - rolling_max) / rolling_max
max_dd = drawdown.min()
avg_volume = df["Volume"].mean()
sharpe_like = cagr / ann_vol if ann_vol > 0 else 0

# Additional: compute total return, best/worst day, positive day ratio
total_return = (end_price / start_price) - 1
best_day = df["Return"].max()
worst_day = df["Return"].min()
positive_days = (df["Return"] > 0).mean()

kpis = {
    "Annualized Return (CAGR)": f"{cagr:.2%}",
    "Total Cumulative Return": f"{total_return:.2%}",
    "Annualized Volatility": f"{ann_vol:.2%}",
    "Maximum Drawdown": f"{max_dd:.2%}",
    "Average Daily Volume": f"{avg_volume:,.0f}",
    "Sharpe-Like Ratio": f"{sharpe_like:.2f}",
    "Best Daily Return": f"{best_day:.2%}",
    "Worst Daily Return": f"{worst_day:.2%}",
    "Positive Day Ratio": f"{positive_days:.2%}",
    "Observations (Trading Days)": f"{n_days:,}",
    "Date Range": f"{df['Date'].iloc[0].strftime('%d %b %Y')} – {df['Date'].iloc[-1].strftime('%d %b %Y')}",
}

# ── 3. VOLATILITY REGIME DETECTION ───────────────────────────────────────────

# Rolling volatility (21-day = ~1 month, 63-day = ~3 months)
df["Vol21"] = df["LogReturn"].rolling(21).std() * np.sqrt(252)
df["Vol63"] = df["LogReturn"].rolling(63).std() * np.sqrt(252)

# Classify regimes from vol63 using percentile thresholds
vol63_valid = df["Vol63"].dropna()
low_thresh = np.percentile(vol63_valid, 33)
high_thresh = np.percentile(vol63_valid, 67)

def classify_regime(vol):
    if pd.isna(vol):
        return "insufficient-data"
    if vol < low_thresh:
        return "low-vol"
    elif vol < high_thresh:
        return "normal-vol"
    else:
        return "high-vol / crisis"

df["Regime"] = df["Vol63"].apply(classify_regime)

# Regime statistics
regime_stats = {}
for regime in ["low-vol", "normal-vol", "high-vol / crisis"]:
    mask = df["Regime"] == regime
    if mask.any():
        regime_stats[regime] = {
            "days": int(mask.sum()),
            "pct": f"{mask.mean():.1%}",
            "ann_vol": f"{df.loc[mask, 'LogReturn'].std() * np.sqrt(252):.2%}",
            "ann_return": f"{((1 + df.loc[mask, 'Return']).prod() ** (252 / mask.sum()) - 1) if mask.sum() > 0 else 0:.2%}",
            "avg_daily_return": f"{df.loc[mask, 'Return'].mean():.4%}",
        }

# ── 4. SEASONAL ANALYSIS ─────────────────────────────────────────────────────

df["Month"] = df["Date"].dt.month
df["MonthName"] = df["Date"].dt.strftime("%b")
df["Year"] = df["Date"].dt.year
df["DayOfWeek"] = df["Date"].dt.dayofweek
df["Quarter"] = df["Date"].dt.quarter

# Monthly return statistics
monthly_returns = df.groupby("Month").agg(
    avg_return=("Return", "mean"),
    median_return=("Return", "median"),
    std_return=("Return", "std"),
    positive_pct=("Return", lambda x: (x > 0).mean()),
    count=("Return", "count"),
).reset_index()

monthly_returns["avg_return_pct"] = monthly_returns["avg_return"] * 100
monthly_returns["month_name"] = monthly_returns["Month"].apply(
    lambda m: datetime(2000, m, 1).strftime("%b")
)

# ANOVA test: are monthly mean returns significantly different?
month_groups = [df[df["Month"] == m]["Return"].dropna().values for m in range(1, 13)]
# Filter out months that might be empty
month_groups = [g for g in month_groups if len(g) > 0]
anova_result = stats.f_oneway(*month_groups)
kruskal_result = stats.kruskal(*month_groups)

# Annual returns
annual_returns = df.groupby("Year").agg(
    annual_return=("Close", lambda x: x.iloc[-1] / x.iloc[0] - 1),
    ann_vol=("LogReturn", lambda x: x.std() * np.sqrt(252)),
    avg_volume=("Volume", "mean"),
).reset_index()

# ── 5. TAIL RISK / RETURN DISTRIBUTION ───────────────────────────────────────

returns = df["LogReturn"].dropna()
skewness = returns.skew()
kurtosis = returns.kurtosis()  # excess kurtosis
var_95 = np.percentile(returns, 5)
var_99 = np.percentile(returns, 1)
cvar_95 = returns[returns <= var_95].mean()
cvar_99 = returns[returns <= var_99].mean()

# ── 6. MOMENTUM & MOVING AVERAGES ────────────────────────────────────────────

df["MA50"] = df["Close"].rolling(50).mean()
df["MA200"] = df["Close"].rolling(200).mean()
df["VolumeMA50"] = df["Volume"].rolling(50).mean()

# Rate of change (momentum)
df["ROC21"] = df["Close"].pct_change(21)
df["ROC63"] = df["Close"].pct_change(63)

# ── 7. KEY PRICE LEVELS ──────────────────────────────────────────────────────

ath = df["Close"].max()
ath_date = df.loc[df["Close"].idxmax(), "Date"]
decade_prices = {}
for y in [2000, 2005, 2010, 2015, 2020, 2025]:
    subset = df[df["Year"] == y]
    if not subset.empty:
        decade_prices[y] = {
            "close": f"${subset['Close'].iloc[-1]:,.2f}",
            "high": f"${subset['High'].max():,.2f}",
            "low": f"${subset['Low'].min():,.2f}",
        }

# ── 8. PLOTLY CHARTS ─────────────────────────────────────────────────────────

# --- Chart 1: Long-Term Price with MA overlays ---
fig1 = go.Figure()
fig1.add_trace(go.Scatter(x=df["Date"], y=df["Close"], mode="lines",
    name="Close Price", line=dict(color="#B8860B", width=1.5)))
fig1.add_trace(go.Scatter(x=df["Date"], y=df["MA50"], mode="lines",
    name="50-Day MA", line=dict(color="#1f77b4", width=1, dash="dash")))
fig1.add_trace(go.Scatter(x=df["Date"], y=df["MA200"], mode="lines",
    name="200-Day MA", line=dict(color="#d62728", width=1, dash="dot")))
fig1.update_layout(
    title="Gold Price & Moving Averages (2000–2025)",
    xaxis_title="Date", yaxis_title="Price (USD)",
    template="plotly_white", height=500,
    hovermode="x unified",
    legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
)

# --- Chart 2: Volatility Regimes ---
fig2 = go.Figure()
colors_regime = {"low-vol": "#2ca02c", "normal-vol": "#1f77b4", "high-vol / crisis": "#d62728"}
for regime, color in colors_regime.items():
    mask = df["Regime"] == regime
    fig2.add_trace(go.Scatter(x=df.loc[mask, "Date"], y=df.loc[mask, "Vol63"],
        mode="lines", name=regime, line=dict(color=color, width=1)))

fig2.add_hline(y=low_thresh, line_dash="dash", line_color="gray",
    annotation_text=f"Low-Vol Threshold ({low_thresh:.1%})")
fig2.add_hline(y=high_thresh, line_dash="dash", line_color="gray",
    annotation_text=f"High-Vol Threshold ({high_thresh:.1%})")

fig2.update_layout(
    title="Rolling 63-Day Annualized Volatility with Regime Classification",
    xaxis_title="Date", yaxis_title="Annualized Volatility",
    template="plotly_white", height=450,
    hovermode="x unified",
    legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
)

# --- Chart 3: Drawdown ---
fig3 = go.Figure()
fig3.add_trace(go.Scatter(x=df["Date"], y=drawdown * 100, mode="lines",
    name="Drawdown", fill="tozeroy", line=dict(color="#d62728", width=1),
    fillcolor="rgba(214,39,40,0.15)"))
fig3.update_layout(
    title="Drawdown from All-Time Highs",
    xaxis_title="Date", yaxis_title="Drawdown (%)",
    template="plotly_white", height=400,
    yaxis=dict(ticksuffix="%"),
    hovermode="x unified",
)

# --- Chart 4: Monthly Seasonality Heatmap ---
# Pivot: Year x Month of average daily return
heatmap_data = df.pivot_table(
    values="Return", index="Year", columns="Month", aggfunc="mean"
) * 100  # percentage

month_labels = [datetime(2000, m, 1).strftime("%b") for m in range(1, 13)]
fig4 = go.Figure(data=go.Heatmap(
    z=heatmap_data.values,
    x=month_labels,
    y=heatmap_data.index,
    colorscale="RdBu", zmid=0,
    colorbar=dict(title="Avg Daily Return (%)"),
    hovertemplate="Year: %{y}<br>Month: %{x}<br>Return: %{z:.3f}%<extra></extra>",
))
fig4.update_layout(
    title="Average Daily Return by Month and Year (%)",
    xaxis_title="Month", yaxis_title="Year",
    template="plotly_white", height=550,
)

# --- Chart 5: Monthly Average Returns with Error Bars ---
monthly_returns["sem_return"] = monthly_returns["std_return"] / np.sqrt(monthly_returns["count"])
fig5 = go.Figure()
fig5.add_trace(go.Bar(
    x=monthly_returns["month_name"],
    y=monthly_returns["avg_return_pct"],
    error_y=dict(type="data", array=monthly_returns["sem_return"] * 100 * 1.96, visible=True),
    marker=dict(
        color=monthly_returns["avg_return_pct"],
        colorscale="RdBu", cmin=-0.02, cmax=0.02, cmid=0,
        colorbar=dict(title="Avg Return (%)"),
    ),
    name="Avg Daily Return",
))
fig5.add_hline(y=0, line_dash="solid", line_color="gray", line_width=0.5)
fig5.update_layout(
    title=f"Average Daily Return by Month (with 95% CI)<br>ANOVA p={anova_result.pvalue:.4f}, Kruskal-Wallis p={kruskal_result.pvalue:.4f}",
    xaxis_title="Month", yaxis_title="Average Daily Return (%)",
    template="plotly_white", height=420,
)

# --- Chart 6: Return Distribution ---
fig6 = sp.make_subplots(rows=1, cols=2, subplot_titles=("Log Return Distribution", "Q-Q Plot vs Normal"))
hist = go.Histogram(x=returns, nbinsx=80, histnorm="probability density",
    name="Empirical", marker_color="#B8860B", opacity=0.7)
# Overlay normal fit
x_range = np.linspace(returns.min(), returns.max(), 200)
normal_pdf = stats.norm.pdf(x_range, returns.mean(), returns.std())
fig6.add_trace(hist, row=1, col=1)
fig6.add_trace(go.Scatter(x=x_range, y=normal_pdf, mode="lines",
    name=f"Normal Fit (σ={returns.std():.4f})", line=dict(color="black", width=1.5)), row=1, col=1)

# QQ plot
qq = stats.probplot(returns, dist="norm")
fig6.add_trace(go.Scatter(x=qq[0][0], y=qq[0][1], mode="markers",
    name="QQ", marker=dict(size=3, color="#B8860B", opacity=0.4)), row=1, col=2)
# Reference line
slope, intercept, _ = qq[1]
ref_y = slope * np.array(qq[0][0]) + intercept
fig6.add_trace(go.Scatter(x=qq[0][0], y=ref_y, mode="lines",
    name="Normal Reference", line=dict(color="black", width=1)), row=1, col=2)

fig6.update_layout(template="plotly_white", height=420, showlegend=False,
    xaxis_title="Log Return", yaxis_title="Density",
    xaxis2_title="Theoretical Quantiles", yaxis2_title="Sample Quantiles",
)
# Annotate skew/kurtosis
fig6.add_annotation(x=0.04, y=40, text=f"Skewness: {skewness:.3f}<br>Excess Kurtosis: {kurtosis:.3f}<br>VaR 95%: {var_95:.3%}<br>VaR 99%: {var_99:.3%}<br>CVaR 95%: {cvar_95:.3%}<br>CVaR 99%: {cvar_99:.3%}",
    showarrow=False, font=dict(size=10), align="left", bgcolor="rgba(255,255,255,0.8)",
    xref="x domain", yref="y domain", xanchor="right", yanchor="top",
    bordercolor="gray", borderwidth=1, borderpad=4, x=0.98, y=0.95)

# --- Chart 7: Price & Volume Relationship ---
fig7 = sp.make_subplots(rows=2, cols=1, shared_xaxes=True,
    vertical_spacing=0.05,
    subplot_titles=("Price (Close)", "Volume"),
    row_heights=[0.6, 0.4])
fig7.add_trace(go.Scatter(x=df["Date"], y=df["Close"], mode="lines",
    name="Close", line=dict(color="#B8860B", width=1)), row=1, col=1)
fig7.add_trace(go.Bar(x=df["Date"], y=df["Volume"], name="Volume",
    marker_color="#1f77b4", opacity=0.5), row=2, col=1)
fig7.add_trace(go.Scatter(x=df["Date"], y=df["VolumeMA50"], mode="lines",
    name="50-Day Avg Volume", line=dict(color="#d62728", width=1)), row=2, col=1)
fig7.update_layout(
    title="Price and Volume Dynamics",
    template="plotly_white", height=500,
    hovermode="x unified",
    legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
    showlegend=True,
)

# --- Chart 8: Annual Returns Bar ---
fig8 = go.Figure()
bar_colors = ["#d62728" if v < 0 else "#2ca02c" for v in annual_returns["annual_return"]]
fig8.add_trace(go.Bar(x=annual_returns["Year"], y=annual_returns["annual_return"] * 100,
    marker_color=bar_colors, name="Annual Return"))
fig8.add_hline(y=0, line_dash="solid", line_color="gray", line_width=0.5)
fig8.update_layout(
    title="Gold Annual Returns by Year",
    xaxis_title="Year", yaxis_title="Annual Return (%)",
    template="plotly_white", height=420,
    yaxis=dict(ticksuffix="%"),
)

# --- Chart 9: Momentum (ROC) ---
fig9 = go.Figure()
fig9.add_trace(go.Scatter(x=df["Date"], y=df["ROC21"] * 100, mode="lines",
    name="21-Day ROC", line=dict(color="#1f77b4", width=1)))
fig9.add_trace(go.Scatter(x=df["Date"], y=df["ROC63"] * 100, mode="lines",
    name="63-Day ROC", line=dict(color="#d62728", width=1)))
fig9.add_hline(y=0, line_dash="solid", line_color="gray", line_width=0.5)
fig9.update_layout(
    title="Rate of Change (Momentum) Indicators",
    xaxis_title="Date", yaxis_title="Rate of Change (%)",
    template="plotly_white", height=400,
    yaxis=dict(ticksuffix="%"),
    hovermode="x unified",
    legend=dict(orientation="h", yanchor="bottom", y=1.02, xanchor="left", x=0),
)

# ── 9. GENERATE HTML ─────────────────────────────────────────────────────────

def fig_to_html(fig, chart_id):
    """Convert a Plotly figure to an HTML div."""
    return fig.to_html(full_html=False, include_plotlyjs=False, div_id=chart_id)

charts_html = {
    "price_ma": fig_to_html(fig1, "chart_price_ma"),
    "vol_regime": fig_to_html(fig2, "chart_vol_regime"),
    "drawdown": fig_to_html(fig3, "chart_drawdown"),
    "seasonal_heatmap": fig_to_html(fig4, "chart_seasonal_heatmap"),
    "monthly_bars": fig_to_html(fig5, "chart_monthly_bars"),
    "return_dist": fig_to_html(fig6, "chart_return_dist"),
    "price_volume": fig_to_html(fig7, "chart_price_volume"),
    "annual_returns": fig_to_html(fig8, "chart_annual_returns"),
    "momentum": fig_to_html(fig9, "chart_momentum"),
}

# Regime stats table rows
regime_rows = ""
for regime, s in regime_stats.items():
    regime_rows += f"""
    <tr>
        <td class="regime-badge" style="background:{'#2ca02c33' if regime == 'low-vol' else '#1f77b433' if regime == 'normal-vol' else '#d6272833'};">{regime}</td>
        <td>{s['days']:,}</td>
        <td>{s['pct']}</td>
        <td>{s['ann_vol']}</td>
        <td>{s['ann_return']}</td>
        <td>{s['avg_daily_return']}</td>
    </tr>"""

# Monthly stats table
monthly_table_rows = ""
for _, row in monthly_returns.iterrows():
    monthly_table_rows += f"""
    <tr>
        <td>{row['month_name']}</td>
        <td>{row['avg_return']:.4%}</td>
        <td>{row['median_return']:.4%}</td>
        <td>{row['positive_pct']:.1%}</td>
        <td>{row['count']:,}</td>
    </tr>"""

# Key price milestones
milestones = {
    "$1,000": df[df["Close"] >= 1000]["Date"].min(),
    "$1,500": df[df["Close"] >= 1500]["Date"].min(),
    "$2,000": df[df["Close"] >= 2000]["Date"].min(),
    "$2,500": df[df["Close"] >= 2500]["Date"].min(),
    "$3,000": df[df["Close"] >= 3000]["Date"].min(),
    "$4,000": df[df["Close"] >= 4000]["Date"].min(),
