  .regime-badge {{
    font-weight: 600;
    text-transform: capitalize;
  }}

  /* Key Takeaways */
  .takeaway-list {{
    list-style: none;
    padding: 0;
    counter-reset: item;
  }}
  .takeaway-list li {{
    counter-increment: item;
    padding: 14px 18px 14px 52px;
