#!/usr/bin/env python3
"""Gold Price Dynamics Report Generator — produces /app/output/final_report.html"""

import pandas as pd
import numpy as np
from scipy import stats
import plotly.graph_objects as go
import plotly.subplots as sp
from plotly.utils import PlotlyJSONEncoder
import json
from datetime import datetime, timedelta

# ── 1. LOAD & PARSE ──────────────────────────────────────────────────────────

df = pd.read_csv("/app/benchmark/data.csv")
df["Date"] = pd.to_datetime(df["Date"], format="%d-%m-%y")

# Fix two-digit year cutoff: pandas interprets "26" as 2026 correctly via %y,
# but "00"–"68" become 2000–2068 and "69"–"99" become 1969–1999.
# Our data is all 2000+ so we're fine, but let's ensure no pre-2000 dates exist.
mask_old = df["Date"].dt.year < 2000
df.loc[mask_old, "Date"] = df.loc[mask_old, "Date"] + pd.DateOffset(years=100)

df = df.sort_values("Date").reset_index(drop=True)

# Compute log returns
df["LogReturn"] = np.log(df["Close"] / df["Close"].shift(1))
df["Return"] = df["Close"].pct_change()

# ── 2. KPIs ──────────────────────────────────────────────────────────────────

start_price = df["Close"].iloc[0]
end_price = df["Close"].iloc[-1]
n_days = len(df)
n_years = (df["Date"].iloc[-1] - df["Date"].iloc[0]).days / 365.25

cagr = (end_price / start_price) ** (1 / n_years) - 1
ann_vol = df["LogReturn"].std() * np.sqrt(252)
rolling_max = df["Close"].cummax()
drawdown = (df["Close"] - rolling_max) / rolling_max
max_dd = drawdown.min()
avg_volume = df["Volume"].mean()
sharpe_like = cagr / ann_vol if ann_vol > 0 else 0

# Additional: compute total return, best/worst day, positive day ratio
total_return = (end_price / start_price) - 1
best_day = df["Return"].max()
worst_day = df["Return"].min()
positive_days = (df["Return"] > 0).mean()

kpis = {
    "Annualized Return (CAGR)": f"{cagr:.2%}",
    "Total Cumulative Return": f"{total_return:.2%}",
    "Annualized Volatility": f"{ann_vol:.2%}",
    "Maximum Drawdown": f"{max_dd:.2%}",
    "Average Daily Volume": f"{avg_volume:,.0f}",
    "Sharpe-Like Ratio": f"{sharpe_like:.2f}",
    "Best Daily Return": f"{best_day:.2%}",
    "Worst Daily Return": f"{worst_day:.2%}",
    "Positive Day Ratio": f"{positive_days:.2%}",
    "Observations (Trading Days)": f"{n_days:,}",
    "Date Range": f"{df['Date'].iloc[0].strftime('%d %b %Y')} – {df['Date'].iloc[-1].strftime('%d %b %Y')}",
}

# ── 3. VOLATILITY REGIME DETECTION ───────────────────────────────────────────

# Rolling volatility (21-day = ~1 month, 63-day = ~3 months)
df["Vol21"] = df["LogReturn"].rolling(21).std() * np.sqrt(252)
df["Vol63"] = df["LogReturn"].rolling(63).std() * np.sqrt(252)

# Classify regimes from vol63 using percentile thresholds
vol63_valid = df["Vol63"].dropna()
low_thresh = np.percentile(vol63_valid, 33)
high_thresh = np.percentile(vol63_valid, 67)

def classify_regime(vol):
    if pd.isna(vol):
        return "insufficient-data"
    if vol < low_thresh:
        return "low-vol"
    elif vol < high_thresh:
        return "normal-vol"
    else:
        return "high-vol / crisis"

df["Regime"] = df["Vol63"].apply(classify_regime)

# Regime statistics
regime_stats = {}
for regime in ["low-vol", "normal-vol", "high-vol / crisis"]:
    mask = df["Regime"] == regime
    if mask.any():
        regime_stats[regime] = {
            "days": int(mask.sum()),
            "pct": f"{mask.mean():.1%}",
            "ann_vol": f"{df.loc[mask, 'LogReturn'].std() * np.sqrt(252):.2%}",
            "ann_return": f"{((1 + df.loc[mask, 'Return']).prod() ** (252 / mask.sum()) - 1) if mask.sum() > 0 else 0:.2%}",
            "avg_daily_return": f"{df.loc[mask, 'Return'].mean():.4%}",
        }

# ── 4. SEASONAL ANALYSIS ─────────────────────────────────────────────────────

df["Month"] = df["Date"].dt.month
df["MonthName"] = df["Date"].dt.strftime("%b")
df["Year"] = df["Date"].dt.year
df["DayOfWeek"] = df["Date"].dt.dayofweek
df["Quarter"] = df["Date"].dt.quarter

# Monthly return statistics
monthly_returns = df.groupby("Month").agg(
    avg_return=("Return", "mean"),
    median_return=("Return", "median"),
    std_return=("Return", "std"),
    positive_pct=("Return", lambda x: (x > 0).mean()),
    count=("Return", "count"),
).reset_index()

monthly_returns["avg_return_pct"] = monthly_returns["avg_return"] * 100
monthly_returns["month_name"] = monthly_returns["Month"].apply(
    lambda m: datetime(2000, m, 1).strftime("%b")
)

# ANOVA test: are monthly mean returns significantly different?
month_groups = [df[df["Month"] == m]["Return"].dropna().values for m in range(1, 13)]
# Filter out months that might be empty
month_groups = [g for g in month_groups if len(g) > 0]
anova_result = stats.f_oneway(*month_groups)
kruskal_result = stats.kruskal(*month_groups)

# Annual returns
annual_returns = df.groupby("Year").agg(
    annual_return=("Close", lambda x: x.iloc[-1] / x.iloc[0] - 1),
    ann_vol=("LogReturn", lambda x: x.std() * np.sqrt(252)),
    avg_volume=("Volume", "mean"),
).reset_index()

# ── 5. TAIL RISK / RETURN DISTRIBUTION ───────────────────────────────────────

returns = df["LogReturn"].dropna()
skewness = returns.skew()
